        this.pending = {};       // triggers fired since the last advance
        this.active = {};        // triggers visible during the current advance
        this.binds = [];
        Object.keys(SCENE.nodes).forEach(function (id) {
            SCENE.nodes[id].binds.forEach(function (b) {
                self.binds.push({ node: id, prop: b.prop, vm: b.vm, conv: makeConverter(b.converter) });
            });
        });
